const timeStamp = () => new Date().toISOString();
console.log(`[${timeStamp()}] Prepare Shipping Data: Start`);

try {
  // Validate incoming data ($json is the output of 'Get Order Details')
  // The $json object here should also contain $json.config from the "Workflow Configuration" node
  if (!$json || !$json.id || !$json.number || !$json.shipping || !$json.line_items || !$json.line_items.length || !$json.config) {
    const errorMsg = "Missing critical order data or workflow configuration.";
    const errorInput = { orderId: $json && $json.id, orderNumber: $json && $json.number, configPresent: !!($json && $json.config), fullInput: $json };
    console.error(`[${timeStamp()}] Prepare Shipping Data: Error - ${errorMsg}`, errorInput);
    return { 
        json: { 
            isErrorCondition: true, 
            errorNode: "Prepare Shipping Data", 
            errorMessage: errorMsg, 
            errorDetails: "Input validation failed.", 
            errorInputOrderId: $json && $json.id, 
            errorInputOrderNumber: $json && $json.number, 
            errorFullInput: $json 
        }
    }; 
