    month: 'short', 
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  }).replace(',', '');

  const orderDate = new Date($json.date_created);
  const formattedOrderDate = orderDate.toLocaleString('en-US', { 
