  if (sa.company) { deliveryAddressHtml += `<p>${sa.company.replace(/\n/g, '<br>')}</p>`; }
  if (sa.address_1) { deliveryAddressHtml += `<p>${sa.address_1.replace(/\n/g, '<br>')}</p>`; }
  if (sa.address_2) { deliveryAddressHtml += `<p>${sa.address_2.replace(/\n/g, '<br>')}</p>`; }
  let cityLineParts = [];
  if (sa.city) cityLineParts.push(sa.city);
  if (sa.state) cityLineParts.push(sa.state);
  let cityStateString = cityLineParts.join(', ');
  let fullCityStatePostcodeLine = cityStateString;
  if (sa.postcode) { fullCityStatePostcodeLine += (fullCityStatePostcodeLine ? ' - ' : '') + sa.postcode; }
  if (fullCityStatePostcodeLine) { deliveryAddressHtml += `<p>${fullCityStatePostcodeLine}</p>`; }
