  if ($json.billing && $json.billing.phone) { deliveryAddressHtml += `<p>Tel: ${$json.billing.phone}</p>`; } 
  else if (sa.phone) { deliveryAddressHtml += `<p>Tel: ${sa.phone}</p>`; }
  console.log(`[${timeStamp()}] Prepare Shipping Data: Formatted address for Order ID: ${orderId}`);

  const isChilledItem = $json.line_items.some(item => {
    const itemNameLower = item.name ? item.name.toLowerCase() : '';
    return itemNameLower.includes('cold') || itemNameLower.includes('chilled') || itemNameLower.includes('frozen');
