const timeStamp = () => new Date().toISOString();
console.log(`[${timeStamp()}] Prepare Batch Control Data: Start`);

try {
    // Assumes input $json contains fields from the Merge node:
    // uploadedPdfId, uploadedPdfName, displayOrderId, customerName, originalOrderData, batchFileData
    const uploadedPdfId = $json.uploadedPdfId; 
    const uploadedPdfName = $json.uploadedPdfName;
    const displayOrderId = $json.displayOrderId; // This is WC-NUMBER
    const customerName = $json.customerName;
    const originalOrderData = $json.originalOrderData; // Full order data from WooCommerce
    const batchFileBinaryData = $json.batchFileData ? $json.batchFileData.data : null;

    let batchEntries = [];

    if (batchFileBinaryData) {
        console.log(`[${timeStamp()}] Prepare Batch Control Data: Existing batch file found. Parsing...`);
        const batchFileJsonString = Buffer.from(batchFileBinaryData, 'base64').toString('utf8');
        if (batchFileJsonString) {
            try {
                batchEntries = JSON.parse(batchFileJsonString);
                if (!Array.isArray(batchEntries)) {
                    console.warn(`[${timeStamp()}] Prepare Batch Control Data: Batch file content was not an array. Re-initializing.`);
                    batchEntries = [];
                }
            } catch (parseError) {
                console.error(`[${timeStamp()}] Prepare Batch Control Data: Error parsing existing batch JSON. Content: '${batchFileJsonString}'. Error:`, parseError);
                batchEntries = []; // Start fresh if parsing fails
            }
        }
        console.log(`[${timeStamp()}] Prepare Batch Control Data: Parsed ${batchEntries.length} existing entries.`);
    } else {
        console.log(`[${timeStamp()}] Prepare Batch Control Data: No existing batch file found or content was empty. Initializing new batch.`);
    }

    const newEntry = {
        gdrivePdfId: uploadedPdfId,
        gdrivePdfName: uploadedPdfName,
        orderId: displayOrderId, // WC-NUMBER
        wooCommerceOrderId: originalOrderData.id,
        wooCommerceOrderNumber: originalOrderData.number,
        customerName: customerName,
        processedAt: timeStamp()
    };
    batchEntries.push(newEntry);
    console.log(`[${timeStamp()}] Prepare Batch Control Data: Added new entry for Order ID ${displayOrderId}. Total entries: ${batchEntries.length}`);

    const updatedBatchJsonString = JSON.stringify(batchEntries, null, 2);
    const today = new Date().toISOString().split('T')[0];
    const batchControlFileName = `batch_control_${today}.json`;
    const batchControlGdriveFolderPath = `ShippingSlips_Batches/${today}/BatchControl/`;

    return {
        json: {
            batchJsonToUpload: updatedBatchJsonString,
            batchControlFileName: batchControlFileName,
            batchControlGdriveFolderPath: batchControlGdriveFolderPath,
            processedGoogleDriveFileId: uploadedPdfId,
            googleDriveFileName: uploadedPdfName,
            batchFileIdentifier: `${batchControlGdriveFolderPath}${batchControlFileName}`,
            orderData: originalOrderData
        }
    };

} catch (error) {
    console.error(`[${timeStamp()}] Prepare Batch Control Data: CRITICAL ERROR. Details:`, error.message, error.stack, JSON.stringify($json));
    return { 
        json: {
            isErrorCondition: true,
            errorNode: "Prepare Batch Control Data",
            errorMessage: error.message,
            errorDetails: error.stack,
            errorFullInput: $json // $json is the input to this function node
        }
    };
}

const timeStamp = () => new Date().toISOString();
console.log(`[${timeStamp()}] Parse Batch Control JSON: Start`);

// This node now expects the JSON content of the batch control file as a string,
// or binary data that needs conversion, from a preceding Google Drive Download node.
// Let's assume the GDrive download node output is $json (if it's the first item)
// and its binary data is in $json.data (base64).

try {
    const batchFileBinaryData = $json.data; // From GDrive Download node

    if (!batchFileBinaryData) {
        const msg = `[${timeStamp()}] Parse Batch Control JSON: No batch control file data provided from previous step. Ending.`;
        console.log(msg);
        return [{ json: { status: msg, processed: false, itemsToProcess: [] } }]; // Return one item indicating no processing
    }

    const batchFileJsonString = Buffer.from(batchFileBinaryData, 'base64').toString('utf8');
    if (!batchFileJsonString.trim()) {
        const msg = `[${timeStamp()}] Parse Batch Control JSON: Batch control file is empty. Ending.`;
        console.log(msg);
        return [{ json: { status: msg, processed: false, itemsToProcess: [] } }];
    }

    let batchEntries = [];
    try {
        batchEntries = JSON.parse(batchFileJsonString);
    } catch (e) {
        const msg = `[${timeStamp()}] Parse Batch Control JSON: Error parsing JSON from batch control file. Error: ${e.message}. Content: ${batchFileJsonString}`;
        console.error(msg);
        return [{ 
            json: { 
                isErrorCondition: true, 
                errorNode: "Parse Batch Control JSON", 
                errorMessage: `Error parsing JSON from batch control file: ${e.message}`,
                errorDetails: `Content: ${batchFileJsonString.substring(0, 500)}...`, // Include part of content for debugging
                errorFullInput: $json // The item from GDrive Download node
            }
        }];
    }

    if (!Array.isArray(batchEntries) || batchEntries.length === 0) {
        const msg = `[${timeStamp()}] Parse Batch Control JSON: No valid entries found in batch control file or not an array. Length: ${batchEntries.length}. Type: ${typeof batchEntries}`;
        console.log(msg);
        return [{ json: { status: msg, processed: false, itemsToProcess: [] } }];
    }

    console.log(`[${timeStamp()}] Parse Batch Control JSON: Successfully parsed ${batchEntries.length} entries. Preparing items for processing.`);

    return batchEntries.map(entry => ({
        json: {
            googleDriveFileId: entry.gdrivePdfId,
            originalEntry: entry 
        }
    }));

} catch (error) {
    const msg = `[${timeStamp()}] Parse Batch Control JSON: CRITICAL ERROR. Details: ${error.message}`;
    console.error(msg, error.stack, JSON.stringify($json));
    return [{ 
        json: { 
            isErrorCondition: true, 
            errorNode: "Parse Batch Control JSON", 
            errorMessage: error.message, 
            errorDetails: error.stack,
            errorFullInput: $json
        }
    }];
}

const fs = require('fs');
const path = require('path');
const { PDFDocument } = require('pdf-lib');

async function processAndCombine() {
  const timeStamp = () => new Date().toISOString();
  console.log(`[${timeStamp()}] Combine Downloaded PDFs: Start processing. Received ${items.length} items.`);

  const compiledPdfDir = './shipping_slips'; 
  const tempDir = path.join(compiledPdfDir, 'temp'); 

  const todayForFilename = new Date().toISOString().split('T')[0];
  const compiledPdfPath = path.join(compiledPdfDir, `compiled_slips_gdrive_${todayForFilename}.pdf`);

  if (!fs.existsSync(compiledPdfDir)) {
    fs.mkdirSync(compiledPdfDir, { recursive: true });
  }
  if (!fs.existsSync(tempDir)) {
    fs.mkdirSync(tempDir, { recursive: true });
  }

  const sourcePdfPaths = [];
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const tempPdfPath = item.json.fileName; 

    if (!tempPdfPath) {
        console.warn(`[${timeStamp()}] Combine Downloaded PDFs: Item ${i+1}/${items.length} has no fileName property.`);
        continue;
    }

    if (fs.existsSync(tempPdfPath)) {
      sourcePdfPaths.push(tempPdfPath);
      console.log(`[${timeStamp()}] Combine Downloaded PDFs: Added ${tempPdfPath} to combine list.`);
    } else {
      console.warn(`[${timeStamp()}] Combine Downloaded PDFs: Temporary PDF not found for item ${i+1}/${items.length}: ${tempPdfPath}. Original GDrive ID was ${item.json.googleDriveFileId}`);
    }
  }

  if (sourcePdfPaths.length === 0) {
    console.log(`[${timeStamp()}] Combine Downloaded PDFs: No temporary PDFs found to combine.`);
    return [{ json: { status: 'No temporary PDFs found to combine.', processed: false, sourcePdfPaths } }];
  }
  console.log(`[${timeStamp()}] Combine Downloaded PDFs: Attempting to combine ${sourcePdfPaths.length} PDFs.`);

  try {
    const combinedPdf = await PDFDocument.create();
    for (let i = 0; i < sourcePdfPaths.length; i++) {
      const pdfPath = sourcePdfPaths[i];
      console.log(`[${timeStamp()}] Combine Downloaded PDFs: Processing PDF ${i+1}/${sourcePdfPaths.length}: ${pdfPath}`);
      try {
        const pdfBytes = fs.readFileSync(pdfPath);
        const pdfDoc = await PDFDocument.load(pdfBytes);
        const copiedPages = await combinedPdf.copyPages(pdfDoc, pdfDoc.getPageIndices());
        copiedPages.forEach(page => combinedPdf.addPage(page));
        console.log(`[${timeStamp()}] Combine Downloaded PDFs: Successfully added pages from ${pdfPath}`);
      } catch (loadErr) {
        console.error(`[${timeStamp()}] Combine Downloaded PDFs: Error processing temporary PDF ${pdfPath}:`, loadErr.message, loadErr.stack);
      }
    }

    if (combinedPdf.getPageCount() === 0) {
      console.error(`[${timeStamp()}] Combine Downloaded PDFs: Failed to combine any pages from temporary PDFs.`);
      return [{ json: { status: 'Failed to combine any pages from temporary PDFs.', processed: false, sourcePdfPaths } }];
    }

    const combinedPdfBytes = await combinedPdf.save();
    fs.writeFileSync(compiledPdfPath, combinedPdfBytes);
    console.log(`[${timeStamp()}] Combine Downloaded PDFs: Combined PDF successfully created at ${compiledPdfPath} with ${combinedPdf.getPageCount()} pages.`);

    console.log(`[${timeStamp()}] Combine Downloaded PDFs: Cleaning up ${sourcePdfPaths.length} temporary PDF files...`);
    for (const pdfPath of sourcePdfPaths) {
      try {
        fs.unlinkSync(pdfPath);
        console.log(`[${timeStamp()}] Combine Downloaded PDFs: Deleted temporary file ${pdfPath}`);
      } catch (unlinkErr) {
        console.warn(`[${timeStamp()}] Combine Downloaded PDFs: Failed to delete temporary file ${pdfPath}:`, unlinkErr.message);
      }
    }

    return [{ json: { 
      status: `Batch PDF from Google Drive files successfully created. ${combinedPdf.getPageCount()} pages.`, 
      outputPath: compiledPdfPath, 
      processedPdfCount: sourcePdfPaths.length,
      sourcePdfFiles: sourcePdfPaths, 
      processed: true 
    }}];

  } catch (error) {
    console.error(`[${timeStamp()}] Combine Downloaded PDFs: CRITICAL ERROR during PDF combination:`, error.message, error.stack);
    return [{ 
        json: { 
            isErrorCondition: true, 
            errorNode: "Combine Downloaded PDFs", 
            errorMessage: error.message, 
            errorDetails: error.stack,
            errorFullInput: items // items is the full array input to this node
        }
    }];
  }
}

return await processAndCombine();

const timeStamp = () => new Date().toISOString();
const folderData = $json; // Data of the current folder from the loop
const folderName = folderData.name;
const folderCreatedTime = folderData.createdTime; // Assuming GDrive list provides this

console.log(`[${timeStamp()}] [Cleanup] Checking folder: ${folderName} (ID: ${folderData.id}, Created: ${folderCreatedTime})`);

const output = { ...folderData, isOldEnoughForSlipCleanup: false, isOldEnoughForBatchControlCleanup: false, isOldEnoughForFullFolderArchival: false };

// Validate folder name format YYYY-MM-DD
if (!/^\d{4}-\d{2}-\d{2}$/.test(folderName)) {
    console.warn(`[${timeStamp()}] [Cleanup] Folder ${folderName} does not match YYYY-MM-DD format. Skipping.`);
    return { json: { ...output, skipProcessing: true, reason: 'Invalid folder name format' } };
}

const folderDate = new Date(folderName); // Treats YYYY-MM-DD as UTC midnight
if (isNaN(folderDate.getTime())) {
    console.warn(`[${timeStamp()}] [Cleanup] Could not parse date from folder name ${folderName}. Skipping.`);
    return { json: { ...output, skipProcessing: true, reason: 'Invalid date in folder name' } };
}

const now = new Date();

const sevenDaysAgo = new Date(now);
sevenDaysAgo.setDate(now.getDate() - 7);

const thirtyDaysAgo = new Date(now);
thirtyDaysAgo.setDate(now.getDate() - 30);

const ninetyDaysAgo = new Date(now); // For folder archival example
ninetyDaysAgo.setDate(now.getDate() - 90);

output.isOldEnoughForSlipCleanup = folderDate < sevenDaysAgo;
output.isOldEnoughForBatchControlCleanup = folderDate < thirtyDaysAgo;
output.isOldEnoughForFullFolderArchival = folderDate < ninetyDaysAgo;

console.log(`[${timeStamp()}] [Cleanup] Folder ${folderName}: Slips old enough? ${output.isOldEnoughForSlipCleanup}. Batch control old enough? ${output.isOldEnoughForBatchControlCleanup}. Archive old enough? ${output.isOldEnoughForFullFolderArchival}`);

return { json: output };
